const ASSETS = {"/404":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Page not found · PhraseLane</title><meta name=\"description\" content=\"This page could not be found.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Page not found\"><meta property=\"og:description\" content=\"This page could not be found.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/404\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/404\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"><meta name=\"robots\" content=\"noindex\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><span class=\"eyebrow\">404 / A small detour</span><h1>Lost in navigation?</h1><p>The page could not be found.</p><a class=\"button\" href=\"/\">Back to the workspace ↗</a></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/account":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Your account · PhraseLane</title><meta name=\"description\" content=\"Manage your PhraseLane account and subscription access.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Your account\"><meta property=\"og:description\" content=\"Manage your PhraseLane account and subscription access.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/account\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/account\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"><meta name=\"robots\" content=\"noindex\"><script src=\"/app.js\" defer></script></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"wrap\"><div class=\"accountbox\"><span class=\"eyebrow\">Your workspace access</span><h1>Your account.</h1><p id=\"accountState\">Checking account…</p><p id=\"billingState\" class=\"notice\">Checking subscription availability…</p><div id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\"></div><section class=\"card\" data-unsigned><h2>Start an account</h2><p>Your account uses a private recovery key instead of a password. Save it in your password manager: anyone with it can access the account.</p><button id=\"createAccount\" class=\"button\">Create free account</button><h3>Already have a key?</h3><form id=\"loginForm\"><label for=\"loginKey\">Account recovery key</label><input id=\"loginKey\" class=\"field\" type=\"password\" autocomplete=\"off\" placeholder=\"PL-…\" required><button class=\"button secondary\" type=\"submit\">Restore account</button></form></section><section id=\"keyPanel\" class=\"card\" hidden><h2>Save this key now</h2><p>It is shown only once. We cannot recover it for you. Never send it in a translation or share it publicly.</p><p id=\"recoveryKey\" class=\"key\"></p><button id=\"copyKey\" class=\"button secondary\">Copy private key</button></section><section class=\"card\" data-signed hidden><h2>Subscription</h2><p>Pro: $9 USD per month when available. Renews monthly until cancelled. a proposed 50,000 text characters and 120 audio minutes per paid billing period (not available in the free beta), with daily and per-request limits.</p><label class=\"check\"><input id=\"savedKey\" type=\"checkbox\">I have saved my private account key.</label><label class=\"check\"><input id=\"acceptTerms\" type=\"checkbox\">I have read the <a href=\"/terms\">terms</a> and <a href=\"/privacy\">privacy policy</a>.</label><div class=\"row\"><button id=\"subscribe\" class=\"button\" disabled>Continue to secure checkout</button><button id=\"portal\" class=\"button secondary\" hidden>Manage billing / cancel</button><button id=\"logout\" class=\"iconbtn\">Sign out</button></div></section></div></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/app.js":{"content":"'use strict';\nconst $=s=>document.querySelector(s);let config,account={signedIn:false,plan:'free'},seq=0,recognition,recognizing=false;const cache=new Map();\nconst status=(msg,error=false)=>{const e=$('#status');if(e){e.textContent=msg;e.classList.toggle('error',error);}};\nasync function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Request failed.');return j;}\nconst safeAction=fn=>async()=>{try{await fn();}catch(e){status(e.message,true);}};\nasync function translate(){const source=$('#source'),out=$('#output');if(!source)return;const text=source.value.trim(),from=$('#from').value,to=$('#to').value;if(!text){status('Enter a message first.',true);source.focus();return;}const limit=account.plan==='pro'?1000:500;if([...text].length>limit){status(`Keep this message under ${limit} characters.`,true);return;}out.value='';$('#latency').textContent='Measured after translation';if('speechSynthesis' in window)speechSynthesis.cancel();const key=JSON.stringify([text,from,to]);const id=++seq;$('#translate').disabled=true;status('Translating your message…');const start=performance.now();try{let result=cache.get(key),cached=!!result;if(!result){result=await api('/api/translate',{text,source:from,target:to});if(cache.size>=20)cache.delete(cache.keys().next().value);cache.set(key,result);}if(id!==seq)return;out.value=result.text;$('#latency').textContent=cached?'From this tab’s memory':`${((performance.now()-start)/1000).toFixed(2)}s · round trip`;status(cached?'Reused your previous translation. No new server request.':'Translation ready. Check names, numbers and tone before sending.');}catch(e){if(id===seq)status(e.message,true);}finally{if(id===seq)$('#translate').disabled=false;}}\nfunction count(){if($('#count'))$('#count').textContent=`${[...$('#source').value].length} / ${account.plan==='pro'?1000:500}`;}\nfunction invalidate(){if('speechSynthesis' in window)speechSynthesis.cancel();seq++;if($('#translate'))$('#translate').disabled=false;if($('#output'))$('#output').value='';if($('#latency'))$('#latency').textContent='Measured after translation';count();status('Draft changed. Translate it to get a new result.');}\nfunction clear(){if(recognition)recognition.abort();if('speechSynthesis'in window)speechSynthesis.cancel();cache.clear();$('#source').value='';invalidate();status('Draft, translation and this tab’s translation cache cleared.');}\nfunction dictate(){const C=window.SpeechRecognition||window.webkitSpeechRecognition;if(!C){status('Voice input is not supported here. Type or paste your text instead.',true);return;}if(recognizing){recognition.stop();return;}if(!$('#voiceConsent').checked){$('#voiceNotice').hidden=false;$('#voiceConsent').focus();status('Review the voice privacy note and check the box before recording.');return;}recognition=new C();recognition.lang=$('#from').value;recognition.interimResults=true;recognition.continuous=false;let prefix=$('#source').value.trim();recognition.onstart=()=>{recognizing=true;$('#mic').textContent='■ Stop recording';status('Listening… Click Stop recording when done.');};recognition.onresult=e=>{let t='';for(let i=0;i<e.results.length;i++)t+=e.results[i][0].transcript;$('#source').value=(prefix?prefix+' ':'')+t;invalidate();};recognition.onerror=e=>status(e.error==='not-allowed'?'Microphone permission was denied. You can still type.':'Voice input stopped. Try again or type your message.',true);recognition.onend=()=>{recognizing=false;$('#mic').textContent='◉ Voice input';};recognition.start();}\nfunction speak(){if(!('speechSynthesis'in window)){status('Read aloud is unavailable in this browser.',true);return;}const text=$('#output').value;if(!text){status('Translate a message first.',true);return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang=$('#to').value;u.rate=.95;u.onerror=()=>status('Read aloud could not start. Check your browser audio settings.',true);speechSynthesis.speak(u);status('Reading aloud. Voice availability depends on your browser.');}\nfunction download(text,name,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}\nasync function accountRefresh(){account=await api('/api/account');if($('#accountState'))$('#accountState').textContent=account.signedIn?(account.plan==='pro'?`Pro account · ${account.used.toLocaleString()} / ${account.limit.toLocaleString()} characters used this calendar month`:'Free beta account · 10 translations per network per day, up to 500 characters each'):'No account needed for the free translator. Create one when you want to keep subscription access.';for(const e of document.querySelectorAll('[data-signed]'))e.hidden=!account.signedIn;for(const e of document.querySelectorAll('[data-unsigned]'))e.hidden=account.signedIn;if($('#portal'))$('#portal').hidden=account.status==='free';if($('#subscribe'))$('#subscribe').disabled=!account.billing;if($('#billingState'))$('#billingState').textContent=account.billing?'Pro subscriptions are available. Review the terms before checkout.':'Pro is not open for purchase yet. No payment is collected. Free tools are available now.';count();}\nfunction initTranslation(){if(!$('#source'))return;$('#translate').addEventListener('click',translate);$('#source').addEventListener('input',invalidate);$('#from').addEventListener('change',invalidate);$('#to').addEventListener('change',invalidate);$('#source').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();translate();}});$('#swap').addEventListener('click',()=>{let old=$('#from').value;$('#from').value=$('#to').value;$('#to').value=old;const previous=$('#output').value;if(previous)$('#source').value=previous;invalidate();});$('#clear').addEventListener('click',clear);$('#mic').addEventListener('click',safeAction(dictate));$('#speak').addEventListener('click',speak);$('#stopAudio').addEventListener('click',()=>{if('speechSynthesis'in window)speechSynthesis.cancel();});$('#copy').addEventListener('click',safeAction(async()=>{if(!$('#output').value)throw new Error('Translate a message first.');try{await navigator.clipboard.writeText($('#output').value);status('Translation copied.');}catch{$('#output').focus();$('#output').select();status('Copy is unavailable here. The translation is selected; use your device’s Copy command.');}}));$('#export').addEventListener('click',()=>{if(!$('#output').value){status('Translate a message first.',true);return;}download($('#output').value,'phrase-lane-translation.txt');status('Text file downloaded.');});document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{$('#source').value=b.dataset.example;invalidate();$('#source').focus();}));const C=window.SpeechRecognition||window.webkitSpeechRecognition;if(!C){$('#mic').disabled=true;$('#mic').title='Voice input is unavailable in this browser. Type or paste instead.';}}\nfunction initAccount(){if(!$('#createAccount'))return;$('#createAccount').addEventListener('click',safeAction(async()=>{$('#createAccount').disabled=true;try{const r=await api('/api/accounts',{});$('#recoveryKey').textContent=r.recoveryKey;$('#keyPanel').hidden=false;await accountRefresh();status('Account created. Save the key now; it is not shown again.');}finally{$('#createAccount').disabled=false;}}));$('#copyKey').addEventListener('click',safeAction(async()=>{await navigator.clipboard.writeText($('#recoveryKey').textContent);status('Account key copied. Save it privately.');}));$('#loginForm').addEventListener('submit',e=>{e.preventDefault();safeAction(async()=>{await api('/api/login',{key:$('#loginKey').value.trim()});$('#loginKey').value='';await accountRefresh();status('Account restored.');})();});$('#logout').addEventListener('click',safeAction(async()=>{await api('/api/logout',{});$('#keyPanel').hidden=true;$('#recoveryKey').textContent='';await accountRefresh();status('Signed out on this browser.');}));$('#subscribe').addEventListener('click',safeAction(async()=>{const r=await api('/api/checkout',{savedKey:$('#savedKey').checked,acceptedTerms:$('#acceptTerms').checked});const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='checkout.stripe.com')throw new Error('Unexpected checkout destination.');location.assign(u.href);}));$('#portal').addEventListener('click',safeAction(async()=>{const r=await api('/api/portal',{});const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='billing.stripe.com')throw new Error('Unexpected billing destination.');location.assign(u.href);}));const checkout=new URLSearchParams(location.search).get('checkout');if(checkout)safeAction(async()=>{await api('/api/sync',{checkout});history.replaceState(null,'','/account');await accountRefresh();status('Payment confirmed. Pro access is active.');})();}\nfunction initSubtitles(){if(!$('#captions'))return;const stamp=n=>{const h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=Math.floor(n%60);return [h,m,s].map(x=>String(x).padStart(2,'0')).join(':')+',000';};$('#makeSrt').addEventListener('click',()=>{const lines=$('#captions').value.split('\\n').map(x=>x.trim()).filter(Boolean);const seconds=Number($('#duration').value);if(!lines.length){status('Write one caption per line.',true);return;}if(lines.length>200||$('#captions').value.length>20000){status('Use up to 200 lines and 20,000 characters.',true);return;}const result=lines.map((line,i)=>`${i+1}\\n${stamp(i*seconds)} --> ${stamp((i+1)*seconds)}\\n${line}\\n`).join('\\n');$('#srtOutput').value=result;status(`${lines.length} captions created. These are evenly timed drafts; adjust timing to your actual video.`);});$('#saveSrt').addEventListener('click',()=>{if(!$('#srtOutput').value){status('Create captions first.',true);return;}download($('#srtOutput').value,'captions.srt');});$('#clearSrt').addEventListener('click',()=>{$('#captions').value='';$('#srtOutput').value='';status('Captions cleared.');});}\n\nfunction initClientExamples(){\n if(!$('#source'))return;\n const examples=window.PHRASELANE_EXAMPLES||[];\n const choose=id=>{\n  const example=examples.find(item=>item.id===id);if(!example)return;\n  if(recognition)recognition.abort();\n  $('#from').value='en';$('#to').value='ja';$('#source').value=example.en;\n  invalidate();$('#output').value=example.ja;$('#latency').textContent='Prepared example · EN → JA';\n  status('Example translation. No cloud request made. Edit the English text, then translate your own message.');\n  document.querySelectorAll('[data-client-example]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.clientExample===id)));\n  $('#source').focus({preventScroll:true});\n };\n document.querySelectorAll('[data-client-example]').forEach(button=>button.addEventListener('click',()=>choose(button.dataset.clientExample)));\n for(const id of ['source','from','to'])$('#'+id).addEventListener(id==='source'?'input':'change',()=>document.querySelectorAll('[data-client-example]').forEach(button=>button.setAttribute('aria-pressed','false')));\n const requested=new URLSearchParams(location.search).get('example');if(requested)choose(requested);\n}\n\ninitTranslation();initClientExamples();initAccount();initSubtitles();api('/api/config').then(c=>{config=c;return accountRefresh();}).catch(()=>status('Account status is unavailable. Please reload before using cloud translation.',true));\nwindow.addEventListener('pagehide',()=>{if(recognition)recognition.abort();if('speechSynthesis'in window)speechSynthesis.cancel();cache.clear();});\n","type":"text/javascript; charset=utf-8"},"/billing-policy":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Billing availability · PhraseLane</title><meta name=\"description\" content=\"Billing availability\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Billing availability\"><meta property=\"og:description\" content=\"Billing availability\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/billing-policy\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/billing-policy\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><span class=\"eyebrow\">Payment availability</span><h1>Billing is not open yet.</h1><p class=\"meta\">PhraseLane editorial · Updated 5 October 2026</p><p>The current beta is free. PhraseLane is not accepting Pro purchases and has no paid overage purchases.</p><h2>The planned subscription</h2><p>Pro is planned at $9 USD per month. Its audio and text allowances are being built; they are not available in the beta. See <a href=\"/pricing\">pricing and availability</a> for the current free limits and proposed package.</p><h2>Before a paid launch</h2><p>The final renewal price, billing-period allowances, taxes, supported sales regions, cancellation instructions and refund terms will be displayed before checkout opens. No subscription will begin just because you try an example or create an account.</p><h2>Questions about billing?</h2><p>Use our <a href=\"/contact\">contact page</a>. Do not send card numbers, passwords or your private account recovery key.</p><p><a class=\"button secondary\" href=\"/\">Try the free translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/blog/clarify-client-brief":{"content":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Clarify a Japanese client brief before starting work · PhraseLane</title>\n<meta name=\"description\" content=\"Three English and Japanese examples for confirming deliverables, asking about scope and requesting missing project materials.\">\n<meta name=\"theme-color\" content=\"#175e4b\">\n<meta property=\"og:title\" content=\"Clarify a Japanese client brief before starting work\">\n<meta property=\"og:description\" content=\"Three English and Japanese examples for confirming deliverables, asking about scope and requesting missing project materials.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog/clarify-client-brief\">\n<link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog/clarify-client-brief\">\n<link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<a class=\"skip\" href=\"#main\">Skip to content</a>\n<nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav>\n<main id=\"main\" class=\"article\">\n<article>\n<a href=\"/blog\">← Back to the Journal</a>\n<p class=\"eyebrow\">WORKING WITH JAPANESE CLIENTS</p>\n<h1>Clarify a Japanese client brief before starting work</h1>\n<p class=\"meta\">PhraseLane editorial · Updated <time datetime=\"2026-10-05\">5 October 2026</time> · Practical guide</p>\n\n<p>A short client brief can hide several decisions: which pages are included, who supplies the text and what counts as a revision. Before opening your design or development tools, turn the brief into a small set of questions. For an English-speaking freelancer working with a Japanese client, concrete nouns help both sides check that they mean the same thing.</p>\n<h2>Restate the deliverable first</h2>\n<p>Summarise what you understand before asking the client to correct it. Use the names in their brief, including page titles and file formats. Avoid treating your interpretation as an agreement. “My understanding is…” gives the other person a clear opportunity to confirm or adjust the scope.</p>\n<h3>Example 1: Confirm included pages</h3>\n<p><strong>English:</strong> My understanding is that this project includes the home page and the contact page. Is that correct?</p>\n<p lang=\"ja\"><strong>日本語：</strong>今回の制作範囲は、トップページとお問い合わせページの2ページと理解しております。この認識で相違ないでしょうか。</p>\n<p>The Japanese wording asks whether your understanding differs from theirs. It does not say the scope has already been approved. Keep the page count if it matters: listing two names without a total can leave room for additional pages to be assumed.</p>\n<h2>Ask one question about the uncertain part</h2>\n<p>If “update the images” could mean replacing supplied files or creating new illustrations, ask which action is needed. Avoid putting several unrelated decisions inside one long sentence. Number separate questions when the client needs to answer more than one, and leave room for an answer you did not anticipate.</p>\n<h3>Example 2: Clarify an image request</h3>\n<p><strong>English:</strong> For the new banner, will you provide the image, or would you like me to create it? I will confirm the work involved after your reply.</p>\n<p lang=\"ja\"><strong>日本語：</strong>新しいバナー用の画像はご支給いただけますか。それとも、こちらで制作する想定でしょうか。ご回答をいただいてから、必要な作業内容を確認いたします。</p>\n<p>This message asks about responsibility without offering extra work for free or implying an additional charge. If the answer changes your estimate or delivery date, explain that change separately and agree it before starting the added work.</p>\n<h2>Make missing materials easy to identify</h2>\n<p>“Please send everything” leaves the client to guess what is missing. Name the material, the intended use and the format you can accept. Ask for the latest approved version when drafts exist. Keep private customer details out of example text used in a translation tool.</p>\n<h3>Example 3: Request final copy</h3>\n<p><strong>English:</strong> Could you send the approved English text for the contact page? A Word document or plain text is fine.</p>\n<p lang=\"ja\"><strong>日本語：</strong>お問い合わせページに掲載する、確定済みの英語原稿をお送りいただけますでしょうか。Wordファイルまたはテキストで問題ありません。</p>\n<h2>Before starting</h2>\n<ul><li>List the deliverables and the person supplying each asset.</li><li>Record unanswered questions without filling the gaps yourself.</li><li>Confirm any revised estimate or schedule in the project thread.</li><li>Check that the translated request asks for the same decision as the original.</li></ul>\n\n<p><a class=\"button secondary\" href=\"/?example=scope#workspace\">Try a related example in the translator ↗</a></p>\n<p class=\"meta\">Found something unclear? <a href=\"/contact\">Send a correction</a>.</p>\n</article>\n</main>\n<footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/blog/customer-support-replies":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>A calmer workflow for multilingual support replies · PhraseLane</title><meta name=\"description\" content=\"Create a useful first draft while keeping promises and customer data under control.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"A calmer workflow for multilingual support replies\"><meta property=\"og:description\" content=\"Create a useful first draft while keeping promises and customer data under control.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog/customer-support-replies\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog/customer-support-replies\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">CUSTOMER COMMUNICATION</p><h1>A calmer workflow for multilingual support replies</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Create a useful first draft while keeping promises and customer data under control.</p><h2>Separate the facts from the tone</h2><p>List what you know about the customer’s question before writing a reply. Acknowledge the issue, explain the next action and give a realistic time for an update. Do not add a refund, discount or delivery commitment unless you are authorised to make it. Translation should preserve the promise you actually intend to make.</p><h2>Remove information you do not need</h2><p>A translation usually does not require an order number, address or payment detail. Replace unnecessary personal information with a neutral label before sending text to an external service. Keep the identifying details in your authorised support system and restore them only after the translated draft has been reviewed.</p><h2>Use a small set of clear sentences</h2><p>Try: “Thank you for contacting us. I understand that you could not open the file. Please tell us the device and application you used. We will review the issue and send an update tomorrow.” Adjust the example to match your actual support process. Do not promise a response time you cannot deliver.</p><h2>Review the reply as a complete message</h2><p>After translating, verify the greeting, the request and the next step. Check that a polite sentence has not become an absolute guarantee. If the issue involves safety, legal rights or a disputed charge, use a qualified reviewer and your approved process. Do not rely on a machine-generated response alone.</p><h2>Measure usefulness with real feedback</h2><p>Track whether customers understand the next step and whether your replies reduce repeat questions. Faster drafting is helpful only if it leads to clearer communication. Keep examples free of private customer information when discussing your process with colleagues or creating reusable templates.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/blog/japanese-client-deadlines":{"content":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Confirm a deadline with a Japanese client · PhraseLane</title>\n<meta name=\"description\" content=\"Three English and Japanese examples for confirming delivery dates, requesting feedback and proposing a revised deadline.\">\n<meta name=\"theme-color\" content=\"#175e4b\">\n<meta property=\"og:title\" content=\"Confirm a deadline with a Japanese client\">\n<meta property=\"og:description\" content=\"Three English and Japanese examples for confirming delivery dates, requesting feedback and proposing a revised deadline.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog/japanese-client-deadlines\">\n<link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog/japanese-client-deadlines\">\n<link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<a class=\"skip\" href=\"#main\">Skip to content</a>\n<nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav>\n<main id=\"main\" class=\"article\">\n<article>\n<a href=\"/blog\">← Back to the Journal</a>\n<p class=\"eyebrow\">WORKING WITH JAPANESE CLIENTS</p>\n<h1>Confirm a deadline with a Japanese client</h1>\n<p class=\"meta\">PhraseLane editorial · Updated <time datetime=\"2026-10-05\">5 October 2026</time> · Practical guide</p>\n\n<p>A delivery date can look clear until two people attach different meanings to it. You may mean the first draft; your client may expect finished files. When working from the UK or US with a client in Japan, name the deliverable, the stage and the time zone in the same message. These examples are starting points: replace every project detail before sending.</p>\n<h2>Confirm what will arrive</h2>\n<p>Separate delivery from approval. A draft arriving on Thursday does not mean the client has approved it on Thursday. If their review affects your next task, state that dependency in a separate sentence. Avoid a numeric date such as 10/11, which can be read differently across countries.</p>\n<h3>Example 1: Confirm the first draft</h3>\n<p><strong>English:</strong> I will send the first design draft by 15:00 Japan Standard Time on 12 October. Could you confirm that this timing works for you?</p>\n<p lang=\"ja\"><strong>日本語：</strong>デザインの初稿は、10月12日15時（日本時間）までにお送りします。この日程で問題ないか、ご確認いただけますでしょうか。</p>\n<p>“By” marks the latest delivery time; “at” suggests a specific appointment. The Japanese example uses までに to preserve the deadline. It also calls the file a first draft, so the recipient is not being asked to treat it as final.</p>\n<h2>Give a review request its own deadline</h2>\n<p>A phrase such as “when you have a moment” is polite but leaves the schedule open. Explain what feedback you need and when you need it. If you cannot proceed without it, say so calmly. Do not assume silence means approval.</p>\n<h3>Example 2: Request feedback</h3>\n<p><strong>English:</strong> Could you send your comments on the headings by 12:00 Japan Standard Time on 14 October? I will revise them after receiving your feedback.</p>\n<p lang=\"ja\"><strong>日本語：</strong>見出しについてのご意見を、10月14日12時（日本時間）までにお送りいただけますでしょうか。いただいた内容を確認してから修正いたします。</p>\n<h2>Propose a change before promising it</h2>\n<p>When timing changes, identify the affected item and propose a realistic replacement. A request to extend a deadline is still a request. Wait for agreement before describing the new date as confirmed, and keep the agreed date in your project notes.</p>\n<h3>Example 3: Ask to move delivery</h3>\n<p><strong>English:</strong> I need one additional day to check the revised illustrations. Would delivery by 17:00 Japan Standard Time on 16 October work for you?</p>\n<p lang=\"ja\"><strong>日本語：</strong>修正したイラストの確認に、あと1日必要です。納品を10月16日17時（日本時間）までに変更してもよろしいでしょうか。</p>\n<h2>Before sending</h2>\n<ul><li>Check the month, date, time and time zone against your project calendar.</li><li>Name the exact file or stage: first draft, revised draft or final delivery.</li><li>Keep your commitment distinct from the action you are requesting.</li><li>Check both language versions after changing any number.</li></ul>\n<p>Use the level of formality already established with your client. A clear request and a courteous ending usually leave less room for confusion than adding several layers of apology.</p>\n\n<p><a class=\"button secondary\" href=\"/?example=deadline#workspace\">Try a related example in the translator ↗</a></p>\n<p class=\"meta\">Found something unclear? <a href=\"/contact\">Send a correction</a>.</p>\n</article>\n</main>\n<footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/blog/reschedule-client-meeting":{"content":"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Reschedule a meeting with a Japanese client · PhraseLane</title>\n<meta name=\"description\" content=\"Three English and Japanese messages for proposing new meeting times, checking availability and confirming an agreed change.\">\n<meta name=\"theme-color\" content=\"#175e4b\">\n<meta property=\"og:title\" content=\"Reschedule a meeting with a Japanese client\">\n<meta property=\"og:description\" content=\"Three English and Japanese messages for proposing new meeting times, checking availability and confirming an agreed change.\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog/reschedule-client-meeting\">\n<link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog/reschedule-client-meeting\">\n<link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n<link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n<a class=\"skip\" href=\"#main\">Skip to content</a>\n<nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav>\n<main id=\"main\" class=\"article\">\n<article>\n<a href=\"/blog\">← Back to the Journal</a>\n<p class=\"eyebrow\">WORKING WITH JAPANESE CLIENTS</p>\n<h1>Reschedule a meeting with a Japanese client</h1>\n<p class=\"meta\">PhraseLane editorial · Updated <time datetime=\"2026-10-05\">5 October 2026</time> · Practical guide</p>\n\n<p>Rescheduling is easier when your message helps the client make one decision. Identify the existing meeting, give a short explanation if useful and offer a concrete alternative. When you and your client work in different countries, include the date and time zone even if the original calendar invitation already contains them. These examples use Japan Standard Time to keep the proposed times explicit.</p>\n<h2>Name the meeting you want to move</h2>\n<p>“Can we move tomorrow's call?” can become unclear after an overnight time difference or a delayed reply. Write the calendar date and the purpose of the call instead. A brief apology recognises the inconvenience; it does not need to become a long explanation of your personal schedule.</p>\n<h3>Example 1: Propose a different time</h3>\n<p><strong>English:</strong> I am sorry, but could we move our design review on 15 October from 14:00 to 16:00 Japan Standard Time?</p>\n<p lang=\"ja\"><strong>日本語：</strong>申し訳ありませんが、10月15日のデザイン確認のお打ち合わせを、14時から16時（いずれも日本時間）に変更していただくことは可能でしょうか。</p>\n<p>The Japanese message keeps the original time and proposed time separate. It asks whether the change is possible rather than announcing a decision. If the meeting length is changing too, make that a separate request.</p>\n<h2>Offer a second option without assuming availability</h2>\n<p>Two useful options can reduce another round of scheduling. Check your own calendar before offering them, and include the planned duration where it helps. Your client's working hours may differ from yours; use their stated availability rather than making assumptions based on location.</p>\n<h3>Example 2: Check another date</h3>\n<p><strong>English:</strong> If 15 October is difficult, would 11:00 Japan Standard Time on 16 October work? I expect the meeting to take 30 minutes.</p>\n<p lang=\"ja\"><strong>日本語：</strong>10月15日のご都合が悪い場合は、10月16日11時（日本時間）はいかがでしょうか。所要時間は30分を予定しております。</p>\n<p>Read “I expect” as a planned duration, not a guarantee that every question will be resolved. If neither option works, ask the client for two suitable times. Keep all alternatives in one thread so a reply clearly refers to the same meeting.</p>\n<h2>Confirm only after receiving agreement</h2>\n<p>A proposed time and an agreed time are different states. Once the client accepts, repeat the date, time zone and duration, then update the invitation. Check the meeting link and guest list too. If you say the invitation has been updated, complete that action before sending the message.</p>\n<h3>Example 3: Confirm the agreed change</h3>\n<p><strong>English:</strong> Thank you for confirming. Our design review is now scheduled for 16 October, 11:00–11:30 Japan Standard Time. I have updated the calendar invitation.</p>\n<p lang=\"ja\"><strong>日本語：</strong>ご確認ありがとうございます。デザイン確認のお打ち合わせは、10月16日11時〜11時30分（日本時間）で承りました。カレンダーの招待を更新いたしました。</p>\n<h2>Before sending</h2>\n<ul><li>Check the original meeting and both proposed slots.</li><li>Use your calendar to verify your local equivalent for the exact date.</li><li>Preserve the time zone and duration in both language versions.</li><li>Replace a tentative invitation with the agreed details.</li></ul>\n\n<p><a class=\"button secondary\" href=\"/?example=reschedule#workspace\">Try a related example in the translator ↗</a></p>\n<p class=\"meta\">Found something unclear? <a href=\"/contact\">Send a correction</a>.</p>\n</article>\n</main>\n<footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/blog/subtitle-draft":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Make an SRT subtitle draft from plain text · PhraseLane</title><meta name=\"description\" content=\"Build a simple caption file, then adjust its timing against the actual video.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Make an SRT subtitle draft from plain text\"><meta property=\"og:description\" content=\"Build a simple caption file, then adjust its timing against the actual video.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog/subtitle-draft\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog/subtitle-draft\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">CREATOR NOTES</p><h1>Make an SRT subtitle draft from plain text</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Build a simple caption file, then adjust its timing against the actual video.</p><h2>Write one thought per line</h2><p>An SRT file contains numbered captions, timing information and text. Start with a plain-text transcript and divide it into readable chunks. Avoid long lines that occupy the whole screen. Our subtitle maker turns each non-empty input line into one caption; it does not listen to your video or automatically recognise speech.</p><h2>Choose a starting duration</h2><p>Select the number of seconds to give each caption. The tool places captions consecutively from the beginning of the timeline. This gives you a draft structure quickly, but speaking pace varies. The generated times are placeholders based on your selected duration, not a claim that the subtitles are synchronised.</p><h2>Export and check in your editor</h2><p>Create the captions and download the .srt file. Import it into an editor that supports SRT. Play the video from the beginning and move caption boundaries to match the speech. Check quiet sections, overlapping dialogue and transitions. Save a copy of the edited file separately from the draft.</p><h2>Translate with context</h2><p>When making another language version, translate complete sentences first and then divide them into readable captions. Word order and text length can change across languages. Keep the original transcript for reference, and verify names, specialist vocabulary and any claims. Machine translation is a draft, not an accessibility or localisation certification.</p><h2>Keep rights and privacy in mind</h2><p>Only create subtitles for material you are authorised to use. The subtitle generator itself runs in the page without uploading the caption text to our server. If you separately send text through the cloud translator, the translation privacy policy applies. Review timing and readability before publishing your final video.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/blog/translate-client-messages":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Write client messages that translate clearly · PhraseLane</title><meta name=\"description\" content=\"Small changes to your original message can make a translation easier to check and less likely to miss your intent.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Write client messages that translate clearly\"><meta property=\"og:description\" content=\"Small changes to your original message can make a translation easier to check and less likely to miss your intent.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog/translate-client-messages\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog/translate-client-messages\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">WORKING ACROSS BORDERS</p><h1>Write client messages that translate clearly</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Small changes to your original message can make a translation easier to check and less likely to miss your intent.</p><h2>Start with one request</h2><p>A translation tool cannot resolve an unclear instruction. Before you translate, ask yourself what the recipient needs to do next. Keep one main request per paragraph. A useful message names the task, gives a deadline and explains what a reply should contain. “Please review the attached draft and confirm the delivery date” is easier to act on than “Let me know what you think when you can.”</p><h2>Make dates and quantities unambiguous</h2><p>Write out month names when a numeric date could be read in more than one way. Add a time zone for a deadline. Keep quantities next to their units and name the currency when discussing a price. Translate the message, then compare these details against the original. Do not assume a fluent sentence proves that every number survived correctly.</p><h2>Replace idioms with direct language</h2><p>Expressions such as “touch base” or “move the goalposts” can become confusing outside their original context. Try “discuss the project” or “change the agreed requirements.” Direct language does not need to sound cold: a short thank-you and a clear request are usually enough. If the tone matters, ask a speaker of the target language to review the result.</p><h2>A message you can adapt</h2><p>Try: “Thank you for reviewing the draft. Could you confirm whether the headings are correct? Please send your feedback by 5 October at 16:00 UTC. I will send the revised version after your reply.” Replace the details, translate it and check the output line by line. This is a writing example, not an approved legal or contractual template.</p><h2>Use a human check when the stakes rise</h2><p>Routine project messages are a useful place to start. Contracts, medical information, safety instructions and official documents need qualified review. PhraseLane produces machine translations; it does not certify them. Keep confidential customer information out of a cloud translation request unless you are authorised to share it.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/blog/translation-privacy":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Before you paste: a translation privacy checklist · PhraseLane</title><meta name=\"description\" content=\"Know which tool processes your text and decide what should stay out of it.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Before you paste: a translation privacy checklist\"><meta property=\"og:description\" content=\"Know which tool processes your text and decide what should stay out of it.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog/translation-privacy\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog/translation-privacy\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">PRIVACY BY PRACTICE</p><h1>Before you paste: a translation privacy checklist</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Know which tool processes your text and decide what should stay out of it.</p><h2>Identify the processing route</h2><p>Different tools move information differently. PhraseLane sends a cloud translation request to its Cloudflare Worker and Workers AI. Voice input may be processed by your browser provider. Reading aloud depends on the voices available in your browser or operating system. The local subtitle maker formats text in the page.</p><h2>Remove secrets and unnecessary details</h2><p>Do not paste passwords, authentication codes, payment card details or documents that you are not authorised to share. For an ordinary customer message, replace names and account references before translation when they are not needed for meaning. Keep your original in the system where it belongs.</p><h2>Understand what we retain</h2><p>The application does not intentionally store translation input, translation output or raw audio in its database. It does store account identifiers, hashed access keys and usage counters where those features are used. Cloudflare and browser providers may process technical data under their own policies. No claim of total anonymity or end-to-end encryption is made.</p><h2>Remember shared devices</h2><p>Your signed-in account uses a secure session cookie. Sign out when using a shared computer. Your account recovery key is a credential: anyone with it can restore access, so keep it in a password manager and do not include it in a translation. The tool does not automatically save that key to local storage.</p><h2>Use a specialist route for sensitive work</h2><p>Some information belongs in an approved organisational translation workflow. Check your employer’s or client’s requirements before handling confidential material. If you need a contractual data-processing agreement, regulated-document workflow or certified translation, do not assume this public beta provides it. Contact the operator with questions before sending the material.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/blog/translation-speed":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>What actually makes a translation feel fast? · PhraseLane</title><meta name=\"description\" content=\"Understand waiting time without confusing an attractive demo with guaranteed performance.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"What actually makes a translation feel fast?\"><meta property=\"og:description\" content=\"Understand waiting time without confusing an attractive demo with guaranteed performance.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog/translation-speed\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog/translation-speed\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">A PRACTICAL GUIDE</p><h1>What actually makes a translation feel fast?</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>Understand waiting time without confusing an attractive demo with guaranteed performance.</p><h2>Look at the whole round trip</h2><p>A translation request includes your network connection, the service queue, model processing and delivery of the result. PhraseLane displays the measured round-trip time after a successful request. This is a measurement for that request, not a speed promise for the next one. Wi-Fi quality, language pair and service load can all change your experience.</p><h2>Keep the unit of work small</h2><p>Short, complete messages are easier to review and quicker to work with than a whole document pasted into one box. Split a long message at paragraph boundaries, not in the middle of a sentence. Keeping related context together matters more than chasing the shortest possible chunk. Free cloud translations are limited to 500 characters per request.</p><h2>Avoid sending on every keystroke</h2><p>Sending a request for every letter can waste your allowance and cause results to arrive out of order. PhraseLane translates when you press the button or use Ctrl/Command + Enter. If you change the text while a request is running, the old result is not inserted into your new draft. This keeps the screen consistent with your latest input.</p><h2>Reuse work carefully</h2><p>PhraseLane can reuse recent translations from the current tab’s memory when the text and both language choices match exactly. It labels a reused result so you know it was not a fresh server request. The cache is not written to browser storage. Clear the workspace or close the tab to discard it.</p><h2>Speed is not accuracy</h2><p>Fast output still needs review. Set aside time to check names, currencies, dates and tone. Use short everyday messages to evaluate whether the service fits your workflow. This launch does not provide simultaneous interpretation, audio-to-audio streaming or a latency service-level agreement.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/blog/voice-notes-to-clear-text":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Turn a voice note into a clear written message · PhraseLane</title><meta name=\"description\" content=\"A short dictation workflow for people who think faster than they type.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Turn a voice note into a clear written message\"><meta property=\"og:description\" content=\"A short dictation workflow for people who think faster than they type.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog/voice-notes-to-clear-text\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog/voice-notes-to-clear-text\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><a href=\"/blog\">← Back to the Journal</a><p class=\"eyebrow\">VOICE & WORKFLOW</p><h1>Turn a voice note into a clear written message</h1><p class=\"meta\">PhraseLane editorial · 2 October 2026 · Practical guide</p><p>A short dictation workflow for people who think faster than they type.</p><h2>Decide the point before recording</h2><p>Start with a single sentence explaining why you are speaking. A voice note usually works better when you separate the context, request and next step. A few seconds of planning helps you avoid long pauses and repeated thoughts. PhraseLane uses your browser’s speech recognition where it is available; you can always type or paste instead.</p><h2>Record only with permission</h2><p>Use the microphone for your own voice, or obtain appropriate permission before recording another person. Browser speech recognition may send audio to the browser provider. Read the privacy note before turning it on. Do not use this workflow for confidential meetings or personal information without understanding the processing involved.</p><h2>Check the transcript before translating</h2><p>Speech recognition can mix up names, numbers and words that sound similar. Read the transcript while comparing it with what you meant to say. Add punctuation and replace vague references such as “that thing” with the actual project or item. Keep the first message short; you can add context in a second paragraph.</p><h2>Translate, then listen once</h2><p>Choose the source and target languages explicitly. Translate your corrected text, then use read aloud if your browser supports the target language. Listening can help you notice missing phrases, but it does not independently verify meaning. Compare dates and quantities with the original and use a fluent reviewer for important communications.</p><h2>Keep a text fallback ready</h2><p>Microphone permissions, device settings and browser support can interrupt dictation. If recording does not start, stop trying repeatedly and use the text field. Do not leave the microphone running while troubleshooting. PhraseLane stops its recognition session when you leave the page; you can also stop recording with the visible button.</p><p><a class=\"button\" href=\"/#workspace\">Try the translator ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/blog":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>The Journal · PhraseLane</title><meta name=\"description\" content=\"Practical guides to clear multilingual messages, voice notes, privacy and subtitles.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"The Journal\"><meta property=\"og:description\" content=\"Practical guides to clear multilingual messages, voice notes, privacy and subtitles.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/blog\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/blog\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"wrap\"><header class=\"hero\"><div><span class=\"eyebrow\">The PhraseLane Journal</span><h1>Work in<br><em>more words.</em></h1></div><p>Original, practical notes on communicating across languages. No shortcuts around clarity.</p></header><div class=\"grid3\"><article class=\"card\"><span class=\"eyebrow\">ENGLISH–JAPANESE CLIENT WORK</span><h2><a href=\"/blog/japanese-client-deadlines\">Confirm deadlines with Japanese clients</a></h2><p>Ask for a specific date, time and time zone before making a commitment.</p><a href=\"/blog/japanese-client-deadlines\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">ENGLISH–JAPANESE CLIENT WORK</span><h2><a href=\"/blog/clarify-client-brief\">Clarify a brief before you start</a></h2><p>Check file formats, quantities and priorities with concrete questions.</p><a href=\"/blog/clarify-client-brief\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">ENGLISH–JAPANESE CLIENT WORK</span><h2><a href=\"/blog/reschedule-client-meeting\">Reschedule a meeting politely</a></h2><p>Propose a new time and wait for confirmation before changing the plan.</p><a href=\"/blog/reschedule-client-meeting\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">WORKING ACROSS BORDERS</span><h2><a href=\"/blog/translate-client-messages\">Write client messages that translate clearly</a></h2><p>Small changes to your original message can make a translation easier to check and less likely to miss your intent.</p><a href=\"/blog/translate-client-messages\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">VOICE & WORKFLOW</span><h2><a href=\"/blog/voice-notes-to-clear-text\">Turn a voice note into a clear written message</a></h2><p>A short dictation workflow for people who think faster than they type.</p><a href=\"/blog/voice-notes-to-clear-text\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">A PRACTICAL GUIDE</span><h2><a href=\"/blog/translation-speed\">What actually makes a translation feel fast?</a></h2><p>Understand waiting time without confusing an attractive demo with guaranteed performance.</p><a href=\"/blog/translation-speed\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">CREATOR NOTES</span><h2><a href=\"/blog/subtitle-draft\">Make an SRT subtitle draft from plain text</a></h2><p>Build a simple caption file, then adjust its timing against the actual video.</p><a href=\"/blog/subtitle-draft\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">CUSTOMER COMMUNICATION</span><h2><a href=\"/blog/customer-support-replies\">A calmer workflow for multilingual support replies</a></h2><p>Create a useful first draft while keeping promises and customer data under control.</p><a href=\"/blog/customer-support-replies\">Read the guide ↗</a></article><article class=\"card\"><span class=\"eyebrow\">PRIVACY BY PRACTICE</span><h2><a href=\"/blog/translation-privacy\">Before you paste: a translation privacy checklist</a></h2><p>Know which tool processes your text and decide what should stay out of it.</p><a href=\"/blog/translation-privacy\">Read the guide ↗</a></article></div></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/client-examples.js":{"content":"'use strict';\n// Prepared examples are local content, never AI responses or customer messages.\nwindow.PHRASELANE_EXAMPLES = Object.freeze([\n  {id:'deadline',group:'Scheduling',label:'Confirm a deadline',en:'Could you confirm whether the deadline is October 20 at 5 pm Japan time?',ja:'締め切りは日本時間10月20日午後5時で間違いないか、ご確認いただけますか。'},\n  {id:'reschedule',group:'Scheduling',label:'Move a meeting',en:'Would it be possible to move our meeting to October 22 at 10 am Japan time?',ja:'打ち合わせを日本時間10月22日午前10時に変更することは可能でしょうか。'},\n  {id:'meeting-time',group:'Scheduling',label:'Check the time zone',en:'Is the meeting time shown in Japan time or your local time?',ja:'記載されている打ち合わせの時刻は、日本時間でしょうか。それとも、そちらの現地時間でしょうか。'},\n  {id:'scope',group:'Confirming the brief',label:'Confirm the deliverables',en:'To confirm, you need three banner images and one logo file. Is that correct?',ja:'確認ですが、必要なものはバナー画像3点とロゴファイル1点でよろしいでしょうか。'},\n  {id:'format',group:'Confirming the brief',label:'Ask for a file format',en:'Which file format would you prefer for the final delivery?',ja:'最終納品のファイル形式は、どの形式をご希望でしょうか。'},\n  {id:'priority',group:'Confirming the brief',label:'Choose a priority',en:'Which of these changes should I work on first?',ja:'これらの修正のうち、どれから先に進めればよろしいでしょうか。'},\n  {id:'delivery',group:'Sending your work',label:'Share the finished files',en:'The final files are ready. Please let me know if you have any trouble opening them.',ja:'最終版のファイルが完成しました。開けない場合はお知らせください。'},\n  {id:'revision',group:'Sending your work',label:'Send a revised version',en:'I have updated the file based on your feedback. Could you review the changes?',ja:'いただいたご意見をもとにファイルを修正しました。変更内容をご確認いただけますか。'},\n  {id:'receipt',group:'Sending your work',label:'Confirm receipt',en:'Could you let me know when you have received the files?',ja:'ファイルを受け取られましたら、お知らせいただけますか。'}\n].map(example=>Object.freeze(example)));\n","type":"text/javascript; charset=utf-8"},"/contact":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>A direct line · PhraseLane</title><meta name=\"description\" content=\"A direct line\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"A direct line\"><meta property=\"og:description\" content=\"A direct line\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/contact\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/contact\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><h1>A direct line</h1><p>Questions about the tools, a translation issue or your account? Contact the operator at <a href=\"mailto:fmfm.stars@gmail.com\">fmfm.stars@gmail.com</a>.</p><h2>Tell us what happened</h2><p>Include the tool name, your browser and a description of the issue. Use a non-sensitive example if a translation behaved unexpectedly. Do not send recovery keys, passwords, payment card details or confidential documents.</p><h2>Account and billing requests</h2><p>For data access, deletion or billing questions, describe your request without sharing your private account key. Identity verification may be needed before account changes. No fixed response-time promise is made during this beta.</p><h2>Report a security issue</h2><p>Send a brief description and steps that demonstrate the problem without accessing another person’s data. Do not perform disruptive testing. We will investigate reports, but this is not a paid bug-bounty programme.</p><p><a class=\"button secondary\" href=\"/\">Return to the tools ↗</a></p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/favicon.svg":{"content":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"64\" height=\"64\" viewBox=\"0 0 64 64\"><rect width=\"64\" height=\"64\" rx=\"18\" fill=\"#175e4b\"/><path d=\"M20 44 44 20M22 20h22v22\" fill=\"none\" stroke=\"#e6f0cc\" stroke-width=\"6\"/></svg>","type":"image/svg+xml"},"/":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Clear messages for Japanese clients · PhraseLane</title><meta name=\"description\" content=\"English–Japanese message examples and a short-text translator for freelancers working with Japanese clients.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Clear messages for Japanese clients\"><meta property=\"og:description\" content=\"English–Japanese message examples and a short-text translator for freelancers working with Japanese clients.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"><script src=\"/client-examples.js\" defer></script><script src=\"/app.js\" defer></script></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"wrap\"><header class=\"hero\"><div><div class=\"eyebrow\"><span class=\"dot\"></span> For freelancers working with Japanese clients</div><h1>Clear words.<br><em>Work moves forward.</em></h1></div><div class=\"heroaside\"><p>Confirm a deadline, clarify a brief or send your finished work. Start with an English–Japanese example, then translate your own short message.</p><div class=\"note\">Free beta · Pro is planned, with sales still closed</div></div></header><section id=\"workspace\" class=\"workspace\" aria-label=\"Translation workspace\"><div class=\"workhead\"><div class=\"tabs\"><a class=\"active\" href=\"/#workspace\">Text & voice</a><a href=\"/tools/subtitle-maker\">Subtitle maker ↗</a></div><span class=\"badge\">PUBLIC BETA · 12 LANGUAGES</span></div><div class=\"panels\"><div class=\"pane\"><div class=\"langbar\"><div><label for=\"from\">TRANSLATE FROM</label><br><select id=\"from\"><option value=\"en\" selected>English</option><option value=\"es\">Spanish</option><option value=\"fr\">French</option><option value=\"de\">German</option><option value=\"it\">Italian</option><option value=\"pt\">Portuguese</option><option value=\"ja\">Japanese</option><option value=\"ko\">Korean</option><option value=\"zh\">Chinese</option><option value=\"ar\">Arabic</option><option value=\"hi\">Hindi</option><option value=\"nl\">Dutch</option></select></div><button class=\"iconbtn\" id=\"swap\" aria-label=\"Swap languages\">⇄</button></div><label class=\"micro\" for=\"source\">Your message</label><textarea id=\"source\" placeholder=\"Write something worth understanding…\" maxlength=\"2000\" spellcheck=\"true\"></textarea><div class=\"panebottom\"><button class=\"iconbtn\" id=\"mic\">◉ Voice input</button><button class=\"iconbtn\" id=\"clear\">Clear</button><span class=\"counter\" id=\"count\">0 / 500</span></div></div><div class=\"pane\"><div class=\"langbar\"><div><label for=\"to\">TRANSLATE INTO</label><br><select id=\"to\"><option value=\"en\">English</option><option value=\"es\">Spanish</option><option value=\"fr\">French</option><option value=\"de\">German</option><option value=\"it\">Italian</option><option value=\"pt\">Portuguese</option><option value=\"ja\" selected>Japanese</option><option value=\"ko\">Korean</option><option value=\"zh\">Chinese</option><option value=\"ar\">Arabic</option><option value=\"hi\">Hindi</option><option value=\"nl\">Dutch</option></select></div><span class=\"badge\" id=\"latency\">Measured after translation</span></div><label class=\"micro\" for=\"output\">Translation</label><textarea id=\"output\" readonly placeholder=\"Your translation will appear here.\" aria-label=\"Translation result\" dir=\"auto\"></textarea><div class=\"panebottom\"><button class=\"iconbtn\" id=\"copy\">Copy</button><button class=\"iconbtn\" id=\"speak\">▷ Read aloud</button><button class=\"iconbtn\" id=\"stopAudio\">Stop audio</button><button class=\"iconbtn\" id=\"export\">↓ .txt</button></div></div></div><div class=\"workfoot\"><div><div id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\">Ready when you are.</div><div class=\"micro\">Cloud translation · 10 requests / day per network · 500 characters each · Ctrl/⌘ + Enter</div></div><button class=\"button\" id=\"translate\">Translate message <span>↗</span></button></div></section><div id=\"voiceNotice\" class=\"notice\" hidden><label class=\"check\"><input id=\"voiceConsent\" type=\"checkbox\">I understand that my browser provider may process my microphone audio. I have permission to record this speech.</label><p>Check this box, then press Voice input again. Audio is not saved by PhraseLane. Browser support and languages vary.</p></div><section class=\"example-section\" aria-labelledby=\"example-title\"><div class=\"sectionhead\"><div><span class=\"eyebrow\">Prepared examples · no AI request</span><h2 id=\"example-title\">What do you need to say?</h2></div><a href=\"/blog\">Read the client-work guides ↗</a></div><div class=\"example-grid\"><div class=\"example-group\"><h3>Scheduling</h3><button class=\"chip\" data-client-example=\"deadline\" aria-pressed=\"false\">Confirm a deadline ↗</button><button class=\"chip\" data-client-example=\"reschedule\" aria-pressed=\"false\">Move a meeting ↗</button><button class=\"chip\" data-client-example=\"meeting-time\" aria-pressed=\"false\">Check the time zone ↗</button></div><div class=\"example-group\"><h3>Confirming the brief</h3><button class=\"chip\" data-client-example=\"scope\" aria-pressed=\"false\">Confirm deliverables ↗</button><button class=\"chip\" data-client-example=\"format\" aria-pressed=\"false\">Choose a file format ↗</button><button class=\"chip\" data-client-example=\"priority\" aria-pressed=\"false\">Ask what comes first ↗</button></div><div class=\"example-group\"><h3>Sending your work</h3><button class=\"chip\" data-client-example=\"delivery\" aria-pressed=\"false\">Share the final files ↗</button><button class=\"chip\" data-client-example=\"revision\" aria-pressed=\"false\">Send revised work ↗</button><button class=\"chip\" data-client-example=\"receipt\" aria-pressed=\"false\">Confirm receipt ↗</button></div></div><p class=\"micro\">Illustrative wording, not a real client conversation. Check the dates, deliverables and tone before sending.</p></section><div class=\"trustrow\"><span>↗ No account needed to try</span><span>◈ Your drafts are not stored in our database</span><span>◎ Actual request time shown</span></div><section class=\"section\"><div class=\"sectionhead\"><div><span class=\"eyebrow\">Small tools. Everyday momentum.</span><h2>One less thing in your way.</h2></div></div><div class=\"grid3\"><article class=\"card\"><span class=\"number\">01 / TRANSLATE</span><h3>Find the right words.</h3><p>Translate short messages between 12 languages. Keep control of the original and check the result before sharing.</p></article><article class=\"card\"><span class=\"number\">02 / SPEAK</span><h3>Think out loud.</h3><p>Dictate in supported browsers, edit the transcript and listen to the translation. A text fallback is always there.</p></article><article class=\"card\"><span class=\"number\">03 / CAPTION</span><h3>Give your words a timeline.</h3><p>Turn one caption per line into SRT, WebVTT and TXT drafts. Adjust the timing in your video editor before publishing.</p><a href=\"/tools/subtitle-maker\">Open subtitle maker ↗</a></article></div></section><section class=\"banner\"><div><span class=\"eyebrow\">Built for a considered workflow</span><h2>Short messages. Clear intent.</h2><p>Machine translation is a starting point. Review names, numbers and tone; use a qualified translator for high-stakes documents.</p></div><a class=\"button secondary\" href=\"/blog/translate-client-messages\">A better writing workflow ↗</a></section><section class=\"section\"><div class=\"sectionhead\"><div><span class=\"eyebrow\">English–Japanese client work</span><h2>Messages you can put to work.</h2></div><a href=\"/blog\">All guides ↗</a></div><div class=\"grid3\"><article class=\"card\"><h3><a href=\"/blog/japanese-client-deadlines\">Confirm deadlines with Japanese clients</a></h3><p>Ask for a specific date, time and time zone before making a commitment.</p><a href=\"/blog/japanese-client-deadlines\">Examples and guide ↗</a></article><article class=\"card\"><h3><a href=\"/blog/clarify-client-brief\">Clarify a brief before you start</a></h3><p>Check file formats, quantities and priorities with concrete questions.</p><a href=\"/blog/clarify-client-brief\">Examples and guide ↗</a></article><article class=\"card\"><h3><a href=\"/blog/reschedule-client-meeting\">Reschedule a meeting politely</a></h3><p>Propose a new time and wait for confirmation before changing the plan.</p><a href=\"/blog/reschedule-client-meeting\">Examples and guide ↗</a></article></div></section><section class=\"section\"><div class=\"sectionhead\"><div><span class=\"eyebrow\">The PhraseLane Journal</span><h2>A few words on better work.</h2></div><a href=\"/blog\">All guides ↗</a></div><div class=\"grid3\"><article class=\"card\"><div class=\"graphic\" aria-hidden=\"true\">Aa</div><span class=\"eyebrow\">WORKING ACROSS BORDERS</span><h3><a href=\"/blog/translate-client-messages\">Write client messages that translate clearly</a></h3><p>Small changes to your original message can make a translation easier to check and less likely to miss your intent.</p><a href=\"/blog/translate-client-messages\">Read the guide ↗</a></article><article class=\"card\"><div class=\"graphic\" aria-hidden=\"true\">∿</div><span class=\"eyebrow\">VOICE & WORKFLOW</span><h3><a href=\"/blog/voice-notes-to-clear-text\">Turn a voice note into a clear written message</a></h3><p>A short dictation workflow for people who think faster than they type.</p><a href=\"/blog/voice-notes-to-clear-text\">Read the guide ↗</a></article><article class=\"card\"><div class=\"graphic\" aria-hidden=\"true\">↗</div><span class=\"eyebrow\">A PRACTICAL GUIDE</span><h3><a href=\"/blog/translation-speed\">What actually makes a translation feel fast?</a></h3><p>Understand waiting time without confusing an attractive demo with guaranteed performance.</p><a href=\"/blog/translation-speed\">Read the guide ↗</a></article></div></section></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/legal":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Seller information / 特定商取引法に基づく表記 · PhraseLane</title><meta name=\"description\" content=\"Seller information / 特定商取引法に基づく表記\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Seller information / 特定商取引法に基づく表記\"><meta property=\"og:description\" content=\"Seller information / 特定商取引法に基づく表記\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/legal\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/legal\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><h1>Seller information / 特定商取引法に基づく表記</h1><div class=\"notice\">Paid subscriptions are not open for purchase. No payment is collected by this website at launch.</div><h2>Operator disclosures</h2><!--SELLER--><p>Before paid sales open, the seller’s legal name, business address, reachable telephone number, contact details and confirmed transaction terms will be displayed here. These details have not yet been supplied for this product.</p><h2>Planned service and charges</h2><p>PhraseLane Pro is planned as a monthly digital translation subscription at $9 USD, subject to the limits on the pricing page. Additional tax, if applicable, must be shown before purchase. An internet connection and compatible browser are required and are the customer’s responsibility.</p><h2>Billing, delivery and cancellation</h2><p>Once enabled, secure hosted checkout will handle payment. Access is activated after server-side payment confirmation. Monthly renewal continues until cancelled through the billing portal. Cancellation prevents future renewal; refunds can be requested through the contact page, subject to applicable consumer rights.</p><p>有料販売は未開始です。販売事業者の正式名称・住所・電話番号などの確認と表示、決済の動作確認が完了するまで購入を受け付けません。</p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/pricing":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Simple, bounded pricing · PhraseLane</title><meta name=\"description\" content=\"Try the free translation tools. Pro is planned at $9 per month with clear usage limits.\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Simple, bounded pricing\"><meta property=\"og:description\" content=\"Try the free translation tools. Pro is planned at $9 per month with clear usage limits.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/pricing\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/pricing\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"wrap\"><header class=\"hero\"><div><span class=\"eyebrow\">Start with something useful</span><h1>A little help.<br><em>A clear limit.</em></h1></div><p>Use the free tools today. Pro is planned at $9 USD per month; paid subscriptions are not open yet.</p></header><div class=\"grid3\"><section class=\"card\"><span class=\"eyebrow\">Free beta</span><h2>Everyday</h2><div class=\"price\">$0</div><ul class=\"featurelist\"><li>10 cloud translations per network / day</li><li>500 characters per translation</li><li>12 language choices</li><li>Browser voice input and read aloud where supported</li><li>Local SRT draft maker</li><li>Copy and text downloads</li></ul><a class=\"button\" href=\"/#workspace\">Try the free tools ↗</a></section><section class=\"card\"><span class=\"eyebrow\">Planned · Not yet on sale</span><h2>Pro</h2><div class=\"price\">$9 <span>USD / month</span></div><ul class=\"featurelist\"><li>Planned: 50,000 text characters per billing period</li><li>Up to 1,000 characters per translation</li><li>Planned: 120 audio minutes per billing period</li><li>Planned: 500 text attempts and 600 audio attempts</li><li>Monthly subscription with cancellation before renewal</li><li>No automatic overage purchases</li></ul><a class=\"button secondary\" href=\"/account\">View account & availability ↗</a><p class=\"micro\">This package is still being built. Audio-minute allowances and billing-period quotas are not available in the current beta. No payment is collected.</p></section><section class=\"card\"><span class=\"eyebrow\">Good to know</span><h2>Useful, with boundaries.</h2><p>Current free beta limits reset daily at 00:00 UTC. Planned Pro allowances will follow its paid billing period. A shared daily cloud capacity limit protects this beta; translations can pause when that capacity is reached.</p><p>No overage charges are added by this app. Unused monthly characters do not roll over. Any applicable tax must be shown before a future purchase.</p><p>No guaranteed latency, certified translation or simultaneous interpretation. Browser voice features vary by device.</p><a href=\"/terms\">Read the terms →</a><p><a href=\"/billing-policy\">Billing availability →</a></p></section></div></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/privacy":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Privacy, plainly · PhraseLane</title><meta name=\"description\" content=\"Privacy, plainly\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Privacy, plainly\"><meta property=\"og:description\" content=\"Privacy, plainly\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/privacy\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/privacy\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><h1>Privacy, plainly</h1><p>Updated 2 October 2026. This page describes the current public beta, not a promise of complete anonymity.</p><h2>Translation and voice</h2><p>Cloud translations send the text and selected languages to our Cloudflare Worker and Cloudflare Workers AI. We do not intentionally write translation input or output to our application database, logs or analytics. Recent identical translations may be kept in the current tab’s memory until you clear it or leave. Cloudflare may process technical data under its own policies.</p><p>Voice input uses your browser’s speech recognition and may send audio to its provider. We ask for acknowledgement before starting the microphone. Read aloud uses browser or operating-system voices, which may use remote services. We do not receive or store raw microphone audio. Browser and device support vary.</p><h2>Local subtitle tool</h2><p>Caption formatting happens in your browser. Its caption text is not uploaded by that tool. If you separately use cloud translation, the translation processing above applies.</p><h2>Account and usage</h2><p>Optional accounts store a random account ID, a hash of the recovery key, creation time, session hashes and any subscription identifiers and status. A secure, HttpOnly, SameSite session cookie keeps you signed in for up to 30 days. Usage controls retain salted hashes derived from network addresses and counters, not the text. Daily records expire after about two days; monthly allowance records expire after about 62 days. An automated cleanup removes expired records.</p><h2>Payments</h2><p>Paid checkout is currently closed. When enabled, Stripe will handle payment details, billing contact information and subscription management on its hosted pages. We do not receive full card numbers. Stripe and our infrastructure providers have their own privacy policies.</p><h2>Your choices</h2><p>You can use free translation without an account. Clear removes the current draft and translation cache; sign out invalidates this browser’s session. Contact us from the contact page for account data access or deletion. Identity must be verified, and transaction records may need to be retained when applicable obligations require it. Do not email your recovery key.</p><h2>No advertising tracking</h2><p>This launch contains no advertising tags, third-party analytics scripts or marketing cookies. We do not sell your translation text. Use an approved specialist workflow for confidential or regulated material. No absolute security or compliance guarantee is made.</p><p>Provider information: <a href=\"https://www.cloudflare.com/privacypolicy/\">Cloudflare privacy policy</a> and <a href=\"https://stripe.com/privacy\">Stripe privacy policy</a>.</p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/style.css":{"content":":root{--ink:#182b3a;--muted:#60727c;--paper:#f6f5f0;--white:#fff;--line:#dfe5df;--green:#175e4b;--lime:#e6f0cc;--orange:#ec6c49;--mono:ui-monospace,SFMono-Regular,Consolas,monospace}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}a{color:inherit}button,input,textarea,select{font:inherit}button,a,textarea,select,input{outline-offset:4px}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:3px solid var(--orange)}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}nav{max-width:1240px;margin:auto;min-height:86px;display:flex;align-items:center;justify-content:space-between;padding:20px 32px;border-bottom:1px solid var(--line);gap:20px}.brand{text-decoration:none;font-size:23px;font-weight:790;letter-spacing:-1px;display:flex;align-items:center;gap:10px}.mark{background:var(--green);color:white;display:inline-grid;place-items:center;width:34px;height:34px;border-radius:10px;font-size:22px}.navlinks{display:flex;align-items:center;gap:28px;font-size:14px}.navlinks a{text-decoration:none}.navlinks a:hover{color:var(--green)}.smallbtn{border:1px solid var(--line);padding:8px 16px;border-radius:8px}.wrap{max-width:1180px;margin:auto;padding:0 28px}.hero{display:grid;grid-template-columns:1.3fr 1fr;gap:45px;align-items:end;padding:64px 0 36px}.eyebrow{font:11px/1.6 var(--mono);text-transform:uppercase;letter-spacing:2px;color:var(--green);display:flex;gap:9px;align-items:center}.dot{width:7px;height:7px;border-radius:50%;background:var(--green)}h1{font-size:clamp(38px,5vw,66px);line-height:1.05;letter-spacing:-3px;margin:18px 0 20px;font-weight:660}h1 em{font:italic 1.03em Georgia,serif;color:var(--green)}.hero p{max-width:460px;color:var(--muted);margin-bottom:12px}.heroaside{padding:0 0 8px 36px;border-left:1px solid var(--line)}.heroaside .note{font:12px var(--mono);margin-top:20px;color:var(--green)}.workspace{background:white;border:1px solid var(--line);border-radius:16px;box-shadow:0 14px 35px #1b383809;overflow:hidden}.workhead{padding:17px 24px;display:flex;justify-content:space-between;align-items:center;gap:14px;background:#fafbf7;border-bottom:1px solid var(--line)}.tabs{display:flex;gap:7px;font-size:13px;align-items:center}.tabs a{padding:7px 14px;text-decoration:none;border-radius:6px}.tabs .active{background:var(--green);color:white}.badge{font:11px var(--mono);color:var(--muted);white-space:nowrap}.panels{display:grid;grid-template-columns:1fr 1fr}.pane{min-width:0;padding:22px 25px}.pane+.pane{border-left:1px solid var(--line);background:#fcfdfb}.langbar{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:17px}.langbar label{font-size:12px;color:var(--muted)}select{border:1px solid var(--line);background:white;border-radius:6px;padding:7px 28px 7px 10px;color:var(--ink);max-width:100%}.iconbtn{background:white;border:1px solid var(--line);border-radius:6px;padding:6px 10px;color:var(--ink)}textarea{width:100%;height:210px;border:0;resize:vertical;color:var(--ink);background:transparent;line-height:1.65;font-size:19px;padding:8px 0}textarea::placeholder{color:#94a09f}.panebottom{display:flex;gap:8px;align-items:center;flex-wrap:wrap;min-height:42px}.counter{margin-left:auto;font:11px var(--mono);color:var(--muted)}.workfoot{border-top:1px solid var(--line);padding:18px 24px;display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.button{display:inline-flex;align-items:center;justify-content:center;gap:16px;border:0;background:var(--green);color:white;padding:12px 22px;border-radius:7px;text-decoration:none;font-weight:600;font-size:14px}.button.secondary{background:var(--lime);color:var(--green)}.button.dark{background:var(--ink)}.micro{font-size:11px;color:var(--muted);line-height:1.7}.status{font-size:13px;min-height:22px;white-space:pre-wrap}.status.error{color:#9a291c}.quickstart{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:20px 0;font-size:12px}.chip{border:1px solid var(--line);background:transparent;border-radius:30px;padding:7px 13px;color:var(--muted);font-size:12px}.chip:hover{background:var(--lime);color:var(--green)}.trustrow{display:flex;gap:25px;justify-content:space-between;border-bottom:1px solid var(--line);padding:16px 0 37px;font-size:12px;color:var(--muted)}.section{padding:62px 0}h2{font-size:32px;letter-spacing:-1px;line-height:1.2;font-weight:650;margin:10px 0 18px}h3{font-size:20px;line-height:1.35}.sectionhead{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:26px}.sectionhead a{font-size:13px;color:var(--green)}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.card{padding:28px;background:white;border:1px solid var(--line);border-radius:12px}.card .number{font:12px var(--mono);color:var(--green)}.card p{font-size:14px;color:var(--muted)}.card a{text-decoration:none}.card a:hover{text-decoration:underline}.graphic{height:150px;border-radius:8px;background:var(--lime);display:grid;place-items:center;margin-bottom:20px;font:italic 50px Georgia;color:var(--green)}.card:nth-child(2) .graphic{background:#e9e8f5;color:#505271}.card:nth-child(3) .graphic{background:#f7e6dc;color:#934c32}.banner{background:var(--ink);color:#fff;border-radius:12px;padding:32px;display:flex;justify-content:space-between;align-items:center;gap:22px}.banner p{color:#c0d0d0;font-size:14px;max-width:580px}.banner .eyebrow{color:#d4e2bd}footer{border-top:1px solid var(--line);margin-top:55px;padding:28px 32px;color:var(--muted);font-size:12px}.footerinner{max-width:1124px;margin:auto;display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap}.footlinks{display:flex;gap:18px}.article{max-width:760px;margin:60px auto;padding:0 26px}.article h1{font-size:44px;letter-spacing:-1.8px}.article h2{font-size:25px;margin-top:36px}.article p,.article li{color:#40535e}.article a{color:var(--green)}.article pre{white-space:pre-wrap;background:#e8ede7;padding:20px;border-radius:8px}.article .meta{font:12px var(--mono);color:var(--muted)}.price{font-size:48px;font-weight:700;letter-spacing:-2px}.price span{font-size:14px;font-weight:400;letter-spacing:0}.featurelist{padding-left:20px;font-size:14px}.notice{background:#eef2e7;padding:18px;border-radius:8px;color:var(--green);font-size:14px}.field{display:block;width:100%;padding:11px;border:1px solid var(--line);border-radius:6px;margin:10px 0}.accountbox{max-width:660px;margin:45px auto}.accountbox .card{margin-bottom:20px}.key{font:12px var(--mono);word-break:break-all;background:#eef2e7;padding:18px;border-radius:6px}.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.check{display:flex;gap:10px;align-items:flex-start;font-size:13px;margin:16px 0}.check input{margin-top:6px}.hidden,[hidden]{display:none!important}.skip{position:absolute;left:15px;top:-70px;z-index:5;background:white;padding:10px}.skip:focus{top:5px}dt{font-weight:700}dd{margin-left:0;margin-bottom:15px}@media(max-width:760px){nav{padding:17px 20px}.navlinks{gap:14px}.navlinks .optional{display:none}.wrap{padding:0 18px}.hero{grid-template-columns:1fr;gap:16px;padding-top:36px}.heroaside{border:0;padding:0}.heroaside p{margin-top:0}h1{letter-spacing:-2px;font-size:45px}.panels{grid-template-columns:1fr}.pane+.pane{border-left:0;border-top:1px solid var(--line)}.pane{padding:18px}textarea{height:160px}.workhead{padding:12px;align-items:start}.tabs a{padding:7px 10px}.badge{font-size:9px}.workfoot{padding:17px}.trustrow{gap:12px;flex-wrap:wrap}.grid3{grid-template-columns:1fr}.section{padding:37px 0}.banner{display:block;padding:25px}.banner .button{margin-top:10px}.article{margin-top:35px}.article h1{font-size:36px}.footerinner{display:block}.footlinks{flex-wrap:wrap;margin-top:15px}.sectionhead{align-items:start}.sectionhead h2{font-size:27px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}\n\n@media(max-width:760px){nav{flex-wrap:wrap}.navlinks{flex-wrap:wrap;gap:8px 14px}.navlinks a,.tabs a{display:inline-flex;align-items:center;min-height:44px}.workhead{flex-wrap:wrap}.badge{white-space:normal;overflow-wrap:anywhere}.langbar{flex-wrap:wrap}.langbar label{min-width:0}.iconbtn,.chip{min-height:44px}select,input{font-size:16px}}\n.example-section{padding:30px 0 16px}.example-section .sectionhead{margin-bottom:18px}.example-section h2{font-size:27px}.example-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.example-group{padding:18px;background:var(--white);border:1px solid var(--line);border-radius:10px}.example-group h3{font-size:15px;margin:0 0 12px}.example-group .chip{display:block;text-align:left;white-space:normal;min-height:44px;margin:6px 0;border-radius:6px;width:100%;color:var(--ink)}.chip[aria-pressed=true]{background:var(--lime);border-color:var(--green)}.article blockquote{margin:18px 0;padding:10px 18px;border-left:3px solid var(--green);background:#eef2e7}.article [lang=ja]{line-height:1.9;overflow-wrap:anywhere}.article .button{color:white}.article .button.secondary{color:var(--green)}.hero{padding-top:40px}.article,.card,.heroaside{min-width:0;overflow-wrap:anywhere}@media(max-width:760px){.example-grid{grid-template-columns:1fr}.example-section .sectionhead{display:block}.hero{padding-top:28px}.example-group{padding:14px}h1{font-size:40px}}\n","type":"text/css; charset=utf-8"},"/terms":{"content":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Terms of use · PhraseLane</title><meta name=\"description\" content=\"Terms of use\"><meta name=\"theme-color\" content=\"#175e4b\"><meta property=\"og:title\" content=\"Terms of use\"><meta property=\"og:description\" content=\"Terms of use\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://phrase-lane-fmfm-stars.pages.dev/terms\"><link rel=\"canonical\" href=\"https://phrase-lane-fmfm-stars.pages.dev/terms\"><link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\"><link rel=\"stylesheet\" href=\"/style.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><nav aria-label=\"Main navigation\"><a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a><div class=\"navlinks\"><a href=\"/#workspace\">Translator</a><a class=\"optional\" href=\"/tools/subtitle-maker\">Subtitles</a><a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a><a class=\"smallbtn optional\" href=\"/account\">Account ↗</a></div></nav><main id=\"main\" class=\"article\"><h1>Terms of use</h1><p>Updated 2 October 2026. PhraseLane is an early-stage language utility for adults aged 18 and over. By using the service, use it only for lawful purposes and material you are authorised to process.</p><h2>Free beta</h2><p>The free cloud service provides up to 10 requests per network address per UTC day, with 500 input characters per request. A shared daily capacity limit may temporarily pause cloud translation. Local tools and browser voice capabilities have their own limits. Availability, latency and translation quality are not guaranteed.</p><h2>Planned Pro subscription</h2><p>Paid subscriptions are not currently offered. If opened, the proposed plan is $9 USD per month with monthly renewal until cancelled, 50,000 text characters and 120 audio minutes per paid billing period, with up to 500 text attempts and 600 audio attempts. These new allowances are under development and are not included in the current free beta. No unused allowance rolls over. No paid overage is automatically added by the app. Final price, any tax and renewal terms must be displayed before checkout.</p><p>Cancellation through the billing portal stops future renewal; access normally continues until the paid period ends. Refund requests can be submitted through the contact page. Mandatory consumer rights remain applicable, and no blanket exclusion of those rights is intended. A purchase will not be enabled until the operator’s sale disclosures are completed.</p><h2>Review before relying on output</h2><p>Machine translation can contain errors or omit context. You are responsible for reviewing names, numbers, tone and meaning. The service does not provide certified translation, medical advice, legal advice, emergency interpretation or safety-critical instructions. Use qualified human review for high-stakes work.</p><h2>Fair and safe use</h2><p>Do not bypass rate limits, attack the service, upload material you have no right to share, impersonate others, conduct fraud or record others without appropriate permission. Access can be limited for abuse or security reasons. The service is supplied without a promise of uninterrupted or error-free operation, subject to rights that cannot lawfully be excluded.</p><h2>Account security</h2><p>Keep your recovery key private. It is the credential that restores your account. We store only its hash and cannot show the original again. Sign out on shared devices. Contact the operator about suspected unauthorised access without sending the key itself.</p><h2>Ownership and contact</h2><p>You retain your rights in your input. Processing your text for a requested translation does not transfer ownership of it to us. Browser providers and payment processors supply their own services under their terms. Contact details and seller information are linked in the footer.</p></main><footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer></body></html>","type":"text/html; charset=utf-8"},"/tools/subtitle-maker":{"content":"<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <title>Free subtitle draft maker · PhraseLane</title>\n  <meta name=\"description\" content=\"Turn one caption per line into SRT, WebVTT or plain text. Preview, copy and download free subtitle drafts directly in your browser.\">\n  <meta name=\"theme-color\" content=\"#175e4b\">\n  <meta property=\"og:title\" content=\"Free subtitle draft maker · PhraseLane\">\n  <meta property=\"og:description\" content=\"Preview, copy and download SRT, WebVTT or plain text drafts. Free local processing in your browser.\">\n  <meta property=\"og:type\" content=\"website\">\n  <meta property=\"og:url\" content=\"https://phrase-lane.fmfm-stars.workers.dev/tools/subtitle-maker\">\n  <link rel=\"canonical\" href=\"https://phrase-lane.fmfm-stars.workers.dev/tools/subtitle-maker\">\n  <link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n  <link rel=\"stylesheet\" href=\"/style.css\">\n  <link rel=\"stylesheet\" href=\"/subtitle-tool.css\">\n  \n  <script src=\"/subtitle-tool.js\" defer></script>\n</head>\n<body>\n  <a class=\"skip\" href=\"#main\">Skip to content</a>\n  <nav aria-label=\"Main navigation\">\n    <a class=\"brand\" href=\"/\"><span class=\"mark\" aria-hidden=\"true\">↗</span>PhraseLane</a>\n    <div class=\"navlinks\">\n      <a href=\"/#workspace\">Translator</a>\n      <a class=\"optional\" href=\"/tools/subtitle-maker\" aria-current=\"page\">Subtitles</a>\n      <a href=\"/blog\">Journal</a><a href=\"/pricing\">Pricing</a>\n      <a class=\"smallbtn optional\" href=\"/account\">Account ↗</a>\n    </div>\n  </nav>\n  <main id=\"main\" class=\"wrap subtitle-tool\">\n    <header class=\"hero\">\n      <div><span class=\"eyebrow\">Free · local · no account needed</span><h1>Words with<br><em>a little timing.</em></h1></div>\n      <p>Give your words a place in the timeline. Paste one caption per line, choose a duration, then save an SRT, WebVTT or text draft.</p>\n    </header>\n    <section class=\"workspace\" aria-label=\"Subtitle draft maker\">\n      <div class=\"workhead\">\n        <div class=\"tabs\"><a href=\"/#workspace\">Text &amp; voice</a><a class=\"active\" href=\"/tools/subtitle-maker\" aria-current=\"page\">Subtitle maker</a></div>\n        <span class=\"badge\">FREE LOCAL TOOL</span>\n      </div>\n      <noscript><p class=\"notice\">Enable JavaScript to generate subtitle drafts in your browser.</p></noscript>\n      <form id=\"subtitleForm\" novalidate>\n        <div class=\"panels\">\n          <div class=\"pane\">\n            <div class=\"subtitle-label-row\"><label for=\"captions\">Your captions</label><button id=\"sampleCaptions\" type=\"button\" class=\"chip\">Try a sample</button></div>\n            <p id=\"captionHelp\" class=\"subtitle-help\">One caption per line. Blank lines are ignored.</p>\n            <textarea id=\"captions\" maxlength=\"20000\" aria-describedby=\"captionHelp captionCount\" placeholder=\"Welcome to our studio.&#10;Today we are sharing a new idea.&#10;Let’s make something worth sharing.\"></textarea>\n            <p id=\"captionCount\" class=\"subtitle-count\">0 / 200 captions · 0 / 20,000 characters</p>\n            <div class=\"subtitle-settings\">\n              <div><label for=\"duration\">Seconds per caption</label><input id=\"duration\" type=\"number\" inputmode=\"numeric\" min=\"1\" max=\"30\" step=\"1\" value=\"3\" required aria-describedby=\"durationHelp\"><p id=\"durationHelp\" class=\"subtitle-help\">Whole seconds, from 1 to 30.</p></div>\n              <div><label for=\"subtitleFormat\">Export format</label><select id=\"subtitleFormat\" aria-describedby=\"formatHelp\"><option value=\"srt\">SRT (.srt)</option><option value=\"vtt\">WebVTT (.vtt)</option><option value=\"txt\">Plain text (.txt)</option></select><p id=\"formatHelp\" class=\"subtitle-help\">Numbered captions with timestamps.</p></div>\n            </div>\n          </div>\n          <div class=\"pane\">\n            <div class=\"subtitle-label-row\"><label id=\"outputLabel\" for=\"srtOutput\">Your SRT draft</label><span id=\"subtitleSummary\" class=\"subtitle-summary\">Ready when you are</span></div>\n            <p id=\"previewHelp\" class=\"subtitle-help\">Check the draft here before saving.</p>\n            <textarea id=\"srtOutput\" readonly spellcheck=\"false\" aria-describedby=\"previewHelp\" placeholder=\"Your generated captions and timestamps will appear here.\"></textarea>\n            <div class=\"row subtitle-export\"><button id=\"copySubtitles\" type=\"button\" class=\"iconbtn\" disabled>Copy draft</button><button id=\"saveSrt\" type=\"button\" class=\"iconbtn\" disabled>Download .srt</button></div>\n          </div>\n        </div>\n        <div class=\"workfoot\">\n          <div id=\"subtitleStatus\" class=\"status\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">Your captions stay in this browser. Start with your own text or try the sample.</div>\n          <div class=\"row\"><button id=\"clearSrt\" type=\"button\" class=\"iconbtn\">Clear</button><button id=\"makeSrt\" type=\"submit\" class=\"button\">Create draft <span aria-hidden=\"true\">↗</span></button></div>\n        </div>\n      </form>\n    </section>\n    <div class=\"subtitle-notes\">\n      <p><strong>A head start on timing.</strong> Every caption uses the same duration, starting at 00:00. Adjust the timing in your video editor to match the speaker.</p>\n      <p><strong>Free in your browser.</strong> No upload, account or subscription is needed for this tool. It formats up to 200 captions and 20,000 characters; it does not transcribe audio or translate text.</p>\n      <p><a href=\"/blog/subtitle-draft\">Read the subtitle workflow →</a></p>\n    </div>\n  </main>\n  <footer><div class=\"footerinner\"><span>PhraseLane · A little less lost in translation.</span><div class=\"footlinks\"><a href=\"/privacy\">Privacy</a><a href=\"/terms\">Terms</a><a href=\"/legal\">Seller information</a><a href=\"/contact\">Contact</a><a href=\"/account\">Account</a></div></div></footer>\n</body>\n</html>\n","type":"text/html; charset=utf-8"},"/subtitle-tool.js":{"content":"'use strict';\n\n(() => {\n  const form = document.getElementById('subtitleForm');\n  if (!form) return;\n\n  const input = document.getElementById('captions');\n  const duration = document.getElementById('duration');\n  const format = document.getElementById('subtitleFormat');\n  const output = document.getElementById('srtOutput');\n  const feedback = document.getElementById('subtitleStatus');\n  const counter = document.getElementById('captionCount');\n  const summary = document.getElementById('subtitleSummary');\n  const copy = document.getElementById('copySubtitles');\n  const save = document.getElementById('saveSrt');\n  const formats = {\n    srt: { label: 'SRT', help: 'Numbered captions with timestamps.', mime: 'application/x-subrip;charset=utf-8' },\n    vtt: { label: 'WebVTT', help: 'Timed captions for web video players.', mime: 'text/vtt;charset=utf-8' },\n    txt: { label: 'plain text', help: 'Caption text only, without timestamps.', mime: 'text/plain;charset=utf-8' }\n  };\n  let result = null;\n  let revision = 0;\n\n  function message(text, error = false) {\n    feedback.textContent = text;\n    feedback.classList.toggle('error', error);\n  }\n\n  function lines() {\n    return input.value.split(/\\r\\n?|\\n/).map(line => line.trim()).filter(Boolean);\n  }\n\n  function count() {\n    const total = lines().length;\n    const characters = input.value.length;\n    counter.textContent = `${total.toLocaleString('en-US')} / 200 captions · ${characters.toLocaleString('en-US')} / 20,000 characters`;\n    counter.classList.toggle('error', total > 200 || characters > 20000);\n  }\n\n  function invalidate() {\n    result = null;\n    revision++;\n    output.value = '';\n    copy.disabled = true;\n    save.disabled = true;\n    summary.textContent = 'Ready when you are';\n    input.removeAttribute('aria-invalid');\n    duration.removeAttribute('aria-invalid');\n    const selected = formats[format.value] || formats.srt;\n    document.getElementById('outputLabel').textContent = `Your ${selected.label} draft`;\n    document.getElementById('formatHelp').textContent = selected.help;\n    save.textContent = `Download .${formats[format.value] ? format.value : 'srt'}`;\n    count();\n  }\n\n  function changed() {\n    const hadResult = Boolean(result);\n    invalidate();\n    message(hadResult ? 'Your input changed. Create a new draft to preview, copy or download it.' : 'Create a draft when your captions and settings are ready.');\n  }\n\n  function stamp(seconds, separator) {\n    const hours = Math.floor(seconds / 3600);\n    const minutes = Math.floor(seconds % 3600 / 60);\n    const remainder = seconds % 60;\n    return [hours, minutes, remainder].map(value => String(value).padStart(2, '0')).join(':') + separator + '000';\n  }\n\n  function fail(text, field) {\n    message(text, true);\n    if (field) {\n      field.setAttribute('aria-invalid', 'true');\n      field.focus();\n    }\n  }\n\n  form.addEventListener('submit', event => {\n    event.preventDefault();\n    invalidate();\n    const captions = lines();\n    const seconds = Number(duration.value);\n    const extension = format.value;\n    if (!captions.length) return fail('Enter at least one caption, or use Try a sample.', input);\n    if (captions.length > 200 || input.value.length > 20000) return fail('Use up to 200 non-empty caption lines and 20,000 characters.', input);\n    if (!duration.value.trim() || !Number.isFinite(seconds) || !Number.isInteger(seconds) || seconds < 1 || seconds > 30) return fail('Enter a whole number of seconds from 1 to 30.', duration);\n    if (!formats[extension]) return fail('Choose SRT, WebVTT or plain text.', format);\n\n    let text;\n    if (extension === 'txt') {\n      text = captions.join('\\n') + '\\n';\n    } else {\n      const separator = extension === 'vtt' ? '.' : ',';\n      const cues = captions.map((caption, index) => {\n        // WebVTT interprets angle brackets and ampersands as cue markup.\n        const captionText = extension === 'vtt' ? caption.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;') : caption;\n        return `${index + 1}\\n${stamp(index * seconds, separator)} --> ${stamp((index + 1) * seconds, separator)}\\n${captionText}`;\n      });\n      text = (extension === 'vtt' ? 'WEBVTT\\n\\n' : '') + cues.join('\\n\\n') + '\\n';\n    }\n    result = { text, extension, mime: formats[extension].mime };\n    output.value = text;\n    copy.disabled = false;\n    save.disabled = false;\n    summary.textContent = extension === 'txt' ? `${captions.length} captions · text only` : `${captions.length} captions · ${stamp(captions.length * seconds, '.').slice(0, -4)} total`;\n    message(extension === 'txt' ? 'Text draft ready. Preview, copy or download your captions.' : 'Draft ready. Preview, copy or download it, then adjust the timing to match your video.');\n  });\n\n  input.addEventListener('input', changed);\n  duration.addEventListener('input', changed);\n  duration.addEventListener('change', changed);\n  format.addEventListener('change', changed);\n\n  document.getElementById('sampleCaptions').addEventListener('click', () => {\n    input.value = 'Welcome to our studio.\\nToday we are sharing a new idea.\\nStart small. Make it useful.\\nThanks for watching.';\n    invalidate();\n    message('Sample loaded. Choose your format, then create a draft.');\n    input.focus();\n  });\n\n  document.getElementById('clearSrt').addEventListener('click', () => {\n    input.value = '';\n    invalidate();\n    message('Captions and draft cleared.');\n    input.focus();\n  });\n\n  copy.addEventListener('click', async () => {\n    if (!result) return;\n    const currentRevision = revision;\n    const text = result.text;\n    try {\n      if (!navigator.clipboard || !navigator.clipboard.writeText) throw new Error('Clipboard unavailable');\n      await navigator.clipboard.writeText(text);\n      if (currentRevision === revision) message('Draft copied to your clipboard.');\n    } catch {\n      if (currentRevision !== revision) return;\n      output.focus();\n      output.select();\n      output.setSelectionRange(0, output.value.length);\n      let copied = false;\n      try { copied = typeof document.execCommand === 'function' && document.execCommand('copy'); } catch { /* Keep selected text available for manual copy. */ }\n      message(copied ? 'Draft copied to your clipboard.' : 'Draft selected. Use your device’s Copy command, or download the file.');\n    }\n  });\n\n  save.addEventListener('click', () => {\n    if (!result) return;\n    let objectUrl;\n    let link;\n    try {\n      objectUrl = URL.createObjectURL(new Blob([result.text], { type: result.mime }));\n      link = document.createElement('a');\n      link.href = objectUrl;\n      link.download = `phraselane-captions.${result.extension}`;\n      document.body.appendChild(link);\n      link.click();\n      message(`Your .${result.extension} download has started. Check your browser’s downloads.`);\n    } catch {\n      message('The file could not be downloaded. Use Copy draft to save the text instead.', true);\n    } finally {\n      if (link) link.remove();\n      if (objectUrl) setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);\n    }\n  });\n\n  invalidate();\n})();\n","type":"text/javascript; charset=utf-8"},"/subtitle-tool.css":{"content":".subtitle-tool .subtitle-label-row{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;min-height:44px}\n.subtitle-tool label{font-size:14px;font-weight:650}\n.subtitle-tool .subtitle-help{font-size:12px;line-height:1.5;color:var(--muted);margin:5px 0 12px}\n.subtitle-tool .subtitle-label-row .chip{margin:0;min-height:40px}\n.subtitle-tool #captions{min-height:220px;border:1px solid var(--line);border-radius:8px;padding:12px;font-size:16px;background:#fff}\n.subtitle-tool .subtitle-count{font:11px/1.6 var(--mono);color:var(--muted);text-align:right;margin:6px 0 20px}\n.subtitle-tool .subtitle-count.error{color:#9a291c}\n.subtitle-tool .subtitle-settings{display:grid;grid-template-columns:1fr 1fr;gap:20px}\n.subtitle-tool .subtitle-settings input,.subtitle-tool .subtitle-settings select{display:block;width:100%;min-height:44px;margin-top:8px;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:#fff;color:var(--ink)}\n.subtitle-tool [aria-invalid=\"true\"]{border-color:#9a291c!important}\n.subtitle-tool #srtOutput{font:13px/1.65 var(--mono);min-height:310px;height:310px;padding:12px;border:1px solid var(--line);border-radius:8px;background:#f5f8f2;white-space:pre-wrap;overflow-wrap:anywhere}\n.subtitle-tool .subtitle-summary{font:11px/1.5 var(--mono);color:var(--green)}\n.subtitle-tool .subtitle-export{margin-top:12px}\n.subtitle-tool .subtitle-export button{min-height:44px}\n.subtitle-tool .workfoot .status{flex:1 1 290px;max-width:670px}\n.subtitle-tool .workfoot>.row{flex-shrink:0}\n.subtitle-notes{display:grid;grid-template-columns:1fr 1fr;gap:0 36px;padding-top:20px;font-size:13px;color:var(--muted)}\n.subtitle-notes strong{color:var(--ink)}\n.subtitle-notes a{color:var(--green)}\n@media(max-width:760px){.subtitle-tool .hero{gap:6px}.subtitle-tool #captions{min-height:190px}.subtitle-tool #srtOutput{height:250px;min-height:250px}.subtitle-tool .subtitle-settings{gap:12px}.subtitle-tool .workfoot>.row{width:100%;justify-content:space-between}.subtitle-tool .workfoot .button{flex:1}.subtitle-notes{grid-template-columns:1fr;gap:0}.subtitle-tool .subtitle-count{font-size:10px}.subtitle-tool .subtitle-label-row{gap:6px}}\n@media(max-width:360px){.subtitle-tool .subtitle-settings{grid-template-columns:1fr}.subtitle-tool .subtitle-count{text-align:left}}\n","type":"text/css; charset=utf-8"}};
const encoder = new TextEncoder();
export const LANGUAGES = {en:'English',es:'Spanish',fr:'French',de:'German',it:'Italian',pt:'Portuguese',ja:'Japanese',ko:'Korean',zh:'Chinese',ar:'Arabic',hi:'Hindi',nl:'Dutch'};
const now = () => Math.floor(Date.now()/1000);
const hex = b => [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('');
export const digest = async s => hex(await crypto.subtle.digest('SHA-256',encoder.encode(s)));
